package com.cryptox.service; import com.cryptox.dto.*; import com.cryptox.model.*; import com.cryptox.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class WalletLedgerService{final WalletRepository wallets; final WalletBalanceRepository balances; final TransactionRepository txs; final WalletAddressGenerator gen; @Value("${app.wallet.starter-balance-usdt}") BigDecimal starter;
@Transactional public Wallet create(String username){if(wallets.existsByOwnerUsername(username)) return byUser(username); String id; do{id=gen.generate();}while(wallets.existsByWalletId(id)); Wallet w=Wallet.builder().walletId(id).ownerUsername(username).build(); w=wallets.save(w); balances.save(WalletBalance.builder().wallet(w).coinSymbol("USDT").amount(starter).build()); return byUser(username);}
public Wallet byUser(String u){return wallets.findByOwnerUsername(u).orElseThrow(()->new IllegalArgumentException("Wallet not found"));} public Wallet byId(String id){return wallets.findByWalletId(id).orElseThrow(()->new IllegalArgumentException("Wallet not found"));}
public WalletResponse response(Wallet w){return new WalletResponse(w.getWalletId(),w.getBalances().stream().map(b->new WalletBalanceDto(b.getCoinSymbol(),b.getAmount())).toList());}
@Transactional public TransactionResponse send(String user,SendCryptoRequest r){Wallet a=byUser(user), b=byId(r.getToWalletId()); if(a.getWalletId().equals(b.getWalletId()))throw new IllegalArgumentException("Cannot send funds to your own wallet"); String c=r.getCoinSymbol().toUpperCase(); WalletBalance ab=balances.findByWalletAndCoinSymbol(a,c).orElseThrow(()->new IllegalArgumentException("You have no "+c+" balance")); if(ab.getAmount().compareTo(r.getAmount())<0)throw new IllegalArgumentException("Insufficient "+c+" balance"); ab.setAmount(ab.getAmount().subtract(r.getAmount())); balances.save(ab); WalletBalance bb=balances.findByWalletAndCoinSymbol(b,c).orElseGet(()->WalletBalance.builder().wallet(b).coinSymbol(c).amount(BigDecimal.ZERO).build()); bb.setAmount(bb.getAmount().add(r.getAmount())); balances.save(bb); Transaction t=txs.save(Transaction.builder().fromWalletId(a.getWalletId()).toWalletId(b.getWalletId()).coinSymbol(c).amount(r.getAmount()).type(TransactionType.SEND).status(TransactionStatus.SUCCESS).note(r.getNote()).build()); return tx(t);}
public List<TransactionResponse> history(String u){Wallet w=byUser(u); return txs.findByFromWalletIdOrToWalletIdOrderByTimestampDesc(w.getWalletId(),w.getWalletId()).stream().map(this::tx).toList();}
@Transactional public InternalTradeResponse trade(InternalTradeRequest r){Wallet w=byUser(r.username()); String from=r.fromCoinSymbol().toUpperCase(),to=r.toCoinSymbol().toUpperCase(); WalletBalance fb=balances.findByWalletAndCoinSymbol(w,from).orElseThrow(()->new IllegalArgumentException("You have no "+from+" balance")); if(fb.getAmount().compareTo(r.fromAmount())<0)throw new IllegalArgumentException("Insufficient "+from+" balance"); fb.setAmount(fb.getAmount().subtract(r.fromAmount())); balances.save(fb); WalletBalance tb=balances.findByWalletAndCoinSymbol(w,to).orElseGet(()->WalletBalance.builder().wallet(w).coinSymbol(to).amount(BigDecimal.ZERO).build()); tb.setAmount(tb.getAmount().add(r.toAmount())); balances.save(tb); TransactionType typ=TransactionType.valueOf(r.type()); Transaction t=txs.save(Transaction.builder().fromWalletId(w.getWalletId()).toWalletId(w.getWalletId()).coinSymbol(from).amount(r.fromAmount()).counterCoinSymbol(to).counterAmount(r.toAmount()).executionPriceUsd(r.executionPriceUsd()).type(typ).status(TransactionStatus.SUCCESS).build()); return new InternalTradeResponse(t.getId(),typ.name(),from,r.fromAmount(),to,r.toAmount(),r.executionPriceUsd(),t.getTimestamp());}
TransactionResponse tx(Transaction t){return new TransactionResponse(t.getId(),t.getFromWalletId(),t.getToWalletId(),t.getCoinSymbol(),t.getAmount(),t.getType(),t.getStatus(),t.getNote(),t.getTimestamp(),t.getCounterCoinSymbol(),t.getCounterAmount(),t.getExecutionPriceUsd());}}